for rel, body in NEW_FILES.items():
    p = ROOT / rel
    if p.exists() and p.read_text() == body:
        print(f"  already   {rel}")
    elif CHECK:
        print(f"  would write {rel}  ({len(body.splitlines())} lines)")
    else:
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(body)
        print(f"  wrote     {rel}  ({len(body.splitlines())} lines)")

done = 0
for rel, pairs in EDITS:
    p = ROOT / rel
    if not p.exists():
        print(f"FAIL: {rel} is missing. Run passes 1-55 first.")
        sys.exit(1)
    t = p.read_text()
    if all(new in t for _, new in pairs):
        print(f"  already   {rel}")
        done += 1
        continue
    for old, new in pairs:
        if t.count(old) != 1:
            print(f"FAIL: {rel}  anchor found {t.count(old)} times, expected 1.")
            print("      Run passes 1-55 first. Stopping without changes.")
            sys.exit(1)
    if not CHECK:
        for old, new in pairs:
            t = t.replace(old, new, 1)
        p.write_text(t)
    print(f"  {'would patch' if CHECK else 'patched  '} {rel}  ({len(pairs)} hunk(s))")

if done == len(EDITS):
    print("  nothing to do - pass 56 is already applied")
